function memoize(fn) {
    const cache = new Map();
    return (x) => {
        if (cache.has(x)) return cache.get(x);
        const result = fn(x);
        cache.set(x, result);
        return result;
    };
}

const fib = memoize(n => n < 2 ? n : fib(n - 1) + fib(n - 2));
console.log(fib(10));

